#include <iostream>
#include <vector>
#include <string>
#include <sstream>
bool load(std::istream& in, std::vector<int>& model) {
  std::string version; int count;
  if (!(in >> version >> count) || version != "EV1" || count < 0 || count > 8) return false;
  std::vector<int> candidate;
  for (int i = 0; i < count; ++i) { int x; if (!(in >> x) || x < 0 || x > 100) return false; candidate.push_back(x); }
  in >> std::ws; if (!in.eof()) return false;
  model.swap(candidate); return true;
}
void save(std::ostream& out, const std::vector<int>& values) { out << "EV1 " << values.size(); for (int x : values) out << ' ' << x; out << '\n'; }
int main() {
  std::vector<int> model{99};
  if (!load(std::cin, model)) { std::cout << "rejected " << model[0] << '\n'; return 0; }
  std::ostringstream bytes; save(bytes, model); std::istringstream input(bytes.str()); std::vector<int> copy;
  if (!load(input, copy) || copy != model) return 1;
  std::cout << bytes.str();
}
